action('practice',openStudentPractice);action('closePractice',closeStudentPractice);action('check',()=>{const good=objects.some(o=>o.type==='book'&&o.boxId===mainBox&&o.rel===taskRelations[taskIndex]);q('.lab-feedback').textContent=good?'✓ Correct! It is '+taskRelations[taskIndex]+' the box.':'Try again. Move the book '+taskRelations[taskIndex]+' the box.';window.answerSignal?.(q('.lab-feedback'),good,q('[data-action="check"]'));if(good){showPrep=showPlace=true;sentence()}});action('solution',()=>{setRelation(get(mainBook),get(mainBox),taskRelations[taskIndex]);showPrep=showPlace=true;sentence();q('.lab-feedback').textContent='Model answer. Try moving the book yourself next.'});action('nextTask',()=>{window.clearAnswerSignals?.(root);taskIndex=(taskIndex+1)%3;task()});
if(practice){q('.lab-demos').hidden=true;q('[data-action="practice"]').hidden=true;q('.lab-practice-actions').hidden=false;q('.lab-add').hidden=true;q('.lab-edit').hidden=true}else q('.lab-task').textContent='';
const tools=document.createElement('details');tools.className='lab-tools-drawer';const toolsLabel=document.createElement('summary');toolsLabel.textContent='⚙ Tools';const toolsPanel=document.createElement('div');toolsPanel.className='lab-drawer-content';for(const selector of ['.lab-add','.lab-penmenu','.lab-edit'])toolsPanel.append(q(selector));tools.append(toolsLabel,toolsPanel);q('.lab-toolbar').insertBefore(tools,q('[data-action="practice"]'));new ResizeObserver(()=>{render();drawInk();updateScan()}).observe(arena);setTool('move');reset(practice);return{start:task};
